const MS_PER_DAY = 86400000;
const now = new Date();
const today = Date.UTC(now.getFullYear(), now.getMonth(), now.getDate());

return $input.all().map(item => {
  const raw = item.json['Last Updated'];
  const d = raw ? new Date(raw) : null;
  const ok = d && !isNaN(d.getTime());
  const last = ok ? Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) : null;

  return {
    json: {
      ...item.json,
      days_since_update: last === null ? null : Math.floor((today - last) / MS_PER_DAY),
    },
  };
});

const result = $input.first().json.output;

const candidates = typeof result === 'string'
  ? JSON.parse(result)
  : result;

// Sort: High first, then Medium, then Low
const priorityOrder = {
  High: 1,
  Medium: 2,
  Low: 3
};

candidates.sort((a, b) =>
  (priorityOrder[a.priority] || 4) -
  (priorityOrder[b.priority] || 4) ||
  b.days_stalled - a.days_stalled
);

const rows = candidates.map(c => `
  <tr>
    <td>${c.candidate}</td>
    <td>${c.stage}</td>
    <td>${c.days_stalled} days</td>
    <td><b>${c.priority}</b></td>
    <td>${c.reason}</td>
    <td>${c.recommended_action}</td>
  </tr>
`).join('');

const html = `
<h2>Hiring Pipeline – Stall Alert Report</h2>
<p>These candidates have been identified as stalled
in the hiring pipeline and may require follow-up.</p>

<table border="1" cellpadding="8"
  cellspacing="0" style="border-collapse:collapse;">
  <tr>
    <th>Candidate</th>
    <th>Stage</th>
    <th>Days Stalled</th>
    <th>Priority</th>
    <th>Reason</th>
    <th>Recommended Action</th>
  </tr>
  ${rows}
</table>

<p><i>Generated automatically by the Stall Alerter.</i></p>
`;

return [{
  json: {
    subject: `Hiring Stall Alert – ${candidates.length} Candidates Need Follow-up`,
    html,
    candidate_count: candidates.length
  }
}];
